contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 burnAmount) public {
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 ownerBalanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(ownerBalanceBefore >= burnAmount);

        c.burn(burnAmount); if (__ESBMC_reverted()) return;

        assert(c.totalSupply() == supplyBefore - burnAmount);
    }
}

