pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 burnAmount) internal {
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 ownerBalanceBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { ownerBalanceBefore = __r; } catch { return; }
        vm.assume(ownerBalanceBefore >= burnAmount);
        try c.burn(burnAmount) {} catch { return; }
        assertTrue(c.totalSupply() == supplyBefore - burnAmount);
    }

    function testFuzz_run(uint256 burnAmount) public {
        _run(burnAmount);
    }

    receive() external payable {}
}
